import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
PG.configure('/festivals/varamahalakshmi/',[('','Varamahālakṣmī Vrata','The Friday of the Boon-Giving Goddess')],'red','Varamahālakṣmī','Devī','Varamahālakṣmī')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/varamahalakshmi/'
i=0
LAK=lambda: devi(sari='#c0392b',items=('lotus','lotus'))
def kalasha_face(): return kalasha()+'<circle cy="-46" r="14" fill="#f2c79b"/><circle cx="-4" cy="-48" r="1.6" fill="#111"/><circle cx="4" cy="-48" r="1.6" fill="#111"/><path d="M-4 -42 q4 3 8 0" fill="none" stroke-width="1.2"/><path d="M-12 -58 l4 -10 l4 6 l4 -8 l4 8 l4 -6 l4 10z" fill="#e0a800"/><circle cy="-52" r="1.5" fill="#c0392b" stroke="none"/>'
def thread(): return '<path d="M-30 0 q30 -20 60 0" fill="none" stroke="#e0a800" stroke-width="4"/>'+''.join(f'<circle cx="{-24+k*6}" cy="{-6-6*__import__("math").sin(k*0.35):.1f}" r="2" fill="#c0392b"/>' for k in range(9))
def bagina(): return '<path d="M-24 0 q24 10 48 0 l-6 -14 h-36z" fill="#c9a06a"/><circle cx="-8" cy="-18" r="5" fill="#e0a800"/><circle cx="6" cy="-18" r="5" fill="#c0392b"/><path d="M-16 -16 q8 -10 16 0" fill="#3a8a4a"/>'
def amalaka(): return '<circle r="8" fill="#e0c040"/><path d="M0 -8 v16 M-7 -4 q7 4 14 0" stroke="#b09020" stroke-width="1" fill="none"/>'
def gold_rain(): return ''.join(f'<g transform="translate({x} {y})">'+amalaka()+'</g>' for x,y in [(-30,-60),(0,-80),(26,-56),(-14,-36),(14,-40),(36,-90),(-40,-96)])
COV=covart('A kalaśa dressed as the goddess Lakṣmī with a face, crown and sari, flanked by lamps, flowers and a plate of fruit',f'<rect width="440" height="196" fill="#f6e3e1"/>'+'<rect y="160" width="440" height="36" fill="#e9c9c3"/>'+g(220,186,2.2,kalasha_face())+'<path d="M180 186 q40 -70 80 0" fill="#c0392b" opacity=".8"/>'+g(110,186,1.6,lamp())+g(330,186,1.6,lamp())+g(60,186,1.4,lotus())+g(390,190,1.3,plate())+g(220,60,1,thread()))
pp=[foreword(i,['On the Friday before the full moon of Śrāvaṇa, Karnataka’s homes turn into palaces for one guest. A brass or silver <b>kalaśa</b> is filled, crowned with a coconut, given a face, dressed in a silk sari and gold, and welcomed at the door as <b>Varamahālakṣmī</b>, Lakṣmī who grants boons (<i>vara</i>). Married women keep the vow for the well-being of their families, tie a yellow thread on the wrist, and give <b>bāgina</b> to other women.','This article tells the vrata story of Cārumatī as the vrata booklets give it, the birth of Lakṣmī from the ocean, the golden rain of the Kanakadhārā, gives two hymns sung on the day, and walks through the kalaśa, the thread, the food and the market rush of a Bengaluru Varamahālakṣmī.'],[('z','Why does Lakṣmī come in a pot?'),('b','The kalaśa is her body for the day, Zappy: full of rice, water and coins, crowned with a coconut. Abundance you can see.')]),
 glance([('Name','Varamahālakṣmī Vrata (Karnataka), Varalakṣmī Vratam (Andhra, Telaṅgāṇa, Tamil Nadu)'),('When','The Friday before Śrāvaṇa Pūrṇimā (July–August); some keep the second Friday of Śrāvaṇa'),('Who','Mainly married women, for the family’s health, long life and prosperity'),('Image','A kalaśa dressed as the goddess, with a painted coconut or a metal face'),('Thread','A turmeric-yellow thread tied round the kalaśa, then on the right wrist'),('Gifts','Bāgina and arisina-kuṅkuma to invited women'),('Story','Cārumatī’s dream (vrata booklets, often attributed to the Skanda Purāṇa)')],svg(560,140,'A dressed kalaśa between lamps',f'<rect width="560" height="140" fill="#f6e3e1"/>'+g(280,130,1.5,kalasha_face())+g(170,130,1.3,lamp())+g(390,130,1.3,lamp())+g(470,130,1.2,bagina()))),
 reading('day','THE FRIDAY OF ŚRĀVAṆA','Why this day',svg(560,160,'A calendar strip of Śrāvaṇa with the Friday before the full moon circled',f'<rect width="560" height="160" fill="#fffaf0"/>'+''.join(f'<rect x="{20+k*36}" y="50" width="32" height="40" rx="4" fill="{"#f6e3e1" if k!=10 else "#c0392b"}" stroke="#111" stroke-width="1.5"/>' for k in range(15))+g(540,70,.7,moonrise(0,0,14))+lab(380,115,'Friday before Pūrṇimā')),['<b>Śrāvaṇa.</b> The monsoon month is sacred to Lakṣmī and to vows: its Fridays (<b>Śrāvaṇa śukravāra</b>) are kept for the goddess in many Karnataka homes, and the greatest of them is Varamahālakṣmī.','<b>The day.</b> The vrata is kept on the Friday that falls just before the full moon of Śrāvaṇa. When that is not possible (illness, travel, mourning), many families keep it on another Friday of the month.','<b>Friday and Lakṣmī.</b> Friday (<i>śukravāra</i>) is the day of Śukra, Venus, the planet of beauty and plenty, and in the South the goddess’s day.','<b>The season of festivals.</b> It falls between '+L('/festivals/naga-panchami/','Nāgara Pañcamī')+' and Gaurī-Gaṇeśa, in the heart of the festival run, and the markets of Bengaluru and Mysuru overflow with flowers and fruit in the days before.'],[('z','Why are flowers so expensive that week?'),('b','Every home in Bengaluru wants them on the same Friday, Zappy!')],'The <b>goddess’s Friday</b>.'),
 story('charumati','CĀRUMATĪ’S DREAM','The vrata story',strip('Three panels: Cārumatī serving her family; Lakṣmī appearing to her in a dream; Cārumatī and the women of the town worshipping a kalaśa',[panel([(person('#c0392b'),1),(god('#7a3fa0'),.8)],'#fff3cf',150),panel([(person('#c0392b',seat=True),.8),(LAK(),.8)],'#3a2a4a',150),panel([(kalasha_face(),1),(person('#c0392b'),.7),(person('#e0a800'),.7)],'#f6e3e1',150)],['a devoted wife','the dream','the vow kept']),'The story read at the end of the worship, as told in vrata booklets (which usually name the Skanda Purāṇa; we have not traced the passage).',['Long ago, in the town of Kuṇḍina in Magadha (tellings vary), lived <b>Cārumatī</b>, a woman devoted to her husband and his parents, honest, kind and diligent in every duty.','Pleased with her, <b>Lakṣmī</b> appeared to her in a dream and said: on the Friday before the full moon of Śrāvaṇa, worship me as Varalakṣmī, and I will grant every boon you ask. (In some tellings it is Viṣṇu who instructs her.)','Cārumatī told the women of the town. On the day they bathed, prepared a kalaśa, and worshipped the goddess with flowers, lamps, sweets and songs, tying the sacred thread on their wrists.','As they walked round the kalaśa, the story says, golden anklets and ornaments appeared on their bodies, and their homes filled with grain and wealth.','The women kept the vow every year, and passed it to their daughters. The kathā ends: whoever keeps it with devotion and hears this story will have health, long life, children and plenty.'],[('z','Where does the story come from?'),('b','From the vrata booklets, Zappy, passed down by families. We tell it as they do, and say honestly that we haven’t found it in a Purāṇa edition.')],'A good woman’s <b>dream</b>.'),
 story('churning','LAKṢMĪ RISES FROM THE OCEAN','Who the goddess is',strip('Three panels: the ocean being churned; Lakṣmī rising on a lotus with elephants pouring water over her; Lakṣmī garlanding Viṣṇu',[panel([(god(),.7),(mountain('#8a7a5a',False),.8),(demon(),.7)],'#dfe9f6',150),panel([(river(144,130),1),(LAK(),.7),(elephant(False),.4)],'#dfe9f6',None),panel([(LAK(),.7),(vishnu(),.7)],'#fff3cf',150)],['the churning','Śrī rises','her choice']),'Bhāgavata Purāṇa 8.8.',['When gods and demons churned the ocean of milk for the nectar of immortality, many treasures rose from the waves.','Among them rose <b>Śrī</b>, Lakṣmī, standing on a lotus, so radiant that everyone gazed at her. The elephants of the quarters poured water over her from golden pots; the ocean gave her silk, Varuṇa a garland of lotuses.','She looked among gods, demons and sages for a husband. Every one had a flaw: anger, pride, want of compassion, desire.','She chose <b>Viṣṇu</b>, who wanted nothing, and placed the lotus garland on him; his chest became her home.','So Lakṣmī is not only money: she is beauty, grace, fortune, good harvest, and the grace that stays with those who do not grasp. (The Dīpāvali night tells another side of her: read our '+L('/festivals/deepavali/','Dīpāvali article')+'.)'],[('z','She chose the one who didn’t want her?'),('b','Wealth stays with those who don’t grab, Zappy. That’s the oldest lesson of Lakṣmī.')],'Śrī chooses <b>the one who wants nothing</b>.'),
 verse('v-mahalakshmi','Mahālakṣmyaṣṭakam, verse 1','Salutations to the great goddess',['namaste ’stu mahāmāye śrīpīṭhe surapūjite','śaṅkhacakragadāhaste mahālakṣmi namo ’stu te'],svg(200,150,'Lakṣmī on a lotus seat holding conch and discus',f'<rect width="200" height="150" fill="#f6e3e1"/>'+g(100,140,1.4,lotus())+g(100,128,1,LAK())+g(60,90,.6,conch())+g(140,90,.6,discus())),'Salutations to you, great Māyā, dwelling in the seat of Śrī, worshipped by the gods; holding conch, discus and mace: O Mahālakṣmī, salutations to you.',[('mahāmāye','O great Māyā'),('śrī-pīṭhe','in the seat of Śrī'),('sura-pūjite','worshipped by the gods'),('śaṅkha-cakra-gadā','conch, discus and mace'),('haste','in whose hands'),('namo ’stu te','salutations to you')],'<b>The hymn of the day.</b> The Mahālakṣmyaṣṭakam, said to be Indra’s praise, is sung in almost every Varamahālakṣmī pūjā in Karnataka. Note that Lakṣmī here holds Viṣṇu’s own weapons: she is his power, not only his consort.',k='The <b>great goddess</b>, saluted.',note='Text as on our '+L('/devi/mahalakshmi-ashtakam/','Mahālakṣmī Aṣṭakam')+' page, which gives all eight verses.'),
 reading('kalasha','THE KALAŚA','The goddess in a pot',svg(560,170,'A kalaśa shown in layers: rice and coins inside, mango leaves, coconut with a face, sari and jewels',f'<rect width="560" height="170" fill="#f6e3e1"/>'+g(160,160,2,kalasha_face())+''.join(lab(380,30+k*24,t) for k,t in enumerate(['coconut: the head, with a face','mango leaves: the crown of life','sari and gold: her dress','rice, coins, betel: inside','thread round the neck']))),['<b>The body.</b> A brass or silver pot is filled with rice (some use water), betel leaves and nuts, turmeric, coins and sometimes small fruits and jewels. Mango leaves are set in its mouth, and a coconut smeared with turmeric is placed on top.','<b>The face.</b> A face of the goddess is painted on the coconut, or a metal face (silver, brass, sometimes gold), often a family heirloom, is fixed on it, with a crown, nose-ring and earrings. The whole is draped in a silk sari and decked with flowers and jewellery.','<b>The welcome.</b> Many families set the dressed kalaśa at the threshold first, as if the goddess were arriving, and carry her in with songs to the decorated maṇṭapa in the pūjā room, often set on a plantain-trunk frame with flowers.','<b>Why a pot.</b> The kalaśa (pūrṇa-kumbha) is the oldest Indian image of abundance: the full pot. Dressed as the goddess, it makes plenty itself into a guest. (Interpretation.)'],[('z','The goddess has a face mask?'),('b','A silver or brass face, often a grandmother’s heirloom, Zappy. The pot becomes her body.')],'Abundance <b>as a guest</b>.'),
 reading('worship','THE DAY’S WORSHIP','From the bath to the thread',svg(560,160,'A woman tying a yellow thread on her wrist before the dressed kalaśa',f'<rect width="560" height="160" fill="#f6e3e1"/>'+'<rect y="135" width="560" height="25" fill="#e9c9c3"/>'+g(170,140,1.4,kalasha_face())+g(320,140,1.2,person('#c0392b'))+g(330,80,.6,thread())+g(450,140,1.2,arati())),['<b>Before.</b> The house is cleaned the day before, rangoli drawn, flowers, fruit, betel and new clothes bought. Many fast until the worship is over.','<b>The pūjā.</b> After the morning bath, Gaṇeśa is worshipped first, then the goddess in the kalaśa with the sixteen services: water, turmeric and kuṅkuma, flowers, incense, lamp, food, and ārati with songs. Many recite the Lakṣmī Aṣṭottara (108 names) and the hymns on these pages.','<b>The thread.</b> A yellow thread (<i>dōra</i>), dipped in turmeric and often with nine knots and a flower tied in, is worshipped with the kalaśa. At the end it is untied and tied on each woman’s right wrist as the goddess’s blessing and protection.','<b>The story.</b> The vrata kathā is read, and the women take akṣata (yellow rice) and place it on the kalaśa. Many families keep the goddess for the day and move her the next morning; in Tamil Nadu she is set in a vessel of rice to “stay” until next year.'],[('z','What does the thread do?'),('b','It carries the goddess’s blessing home on your wrist, Zappy, and reminds you of the vow all year.')],'The vow, <b>tied on the wrist</b>.'),
 story('kanakadhara','THE GOLDEN RAIN','Śaṅkara and the Kanakadhārā',strip('Three panels: the boy Śaṅkara begging at a poor woman’s door; the woman giving her only gooseberry; golden gooseberries raining on the house',[panel([(child(),1),('<rect x="-30" y="-60" width="60" height="60" fill="#c9a06a"/>',1)],'#fff3cf',150),panel([(person('#8a6a4a'),.9),(amalaka(),1.2),(child(),.8)],'#e9d6c0',150),panel([('<rect x="-30" y="-50" width="60" height="50" fill="#c9a06a"/>',1),(gold_rain(),1)],'#f6e3e1',150)],['a boy at the door','her only fruit','the golden rain']),'The traditional origin story of Śaṅkara’s Kanakadhārā Stotram, told in his hagiographies.',['As a young brahmacārī, <b>Śaṅkara</b> went from house to house for alms, as student monks did. He stopped at the door of a very poor brahmin woman.','She had nothing in the house to give, not a grain of rice. Searching, she found one dried <b>āmalaka</b> (Indian gooseberry), and, ashamed, gave him that.','Moved by her giving everything she had, the boy stood at her door and sang a hymn to Lakṣmī, asking the goddess to look with grace on this house.','Pleased, Lakṣmī answered: then and there a rain of <b>golden gooseberries</b> fell on the poor woman’s home.','The hymn became the <b>Kanakadhārā Stotram</b>, “the stream of gold”, and it is sung on Varamahālakṣmī by families across Karnataka, Kerala and beyond.'],[('z','She gave just one dried fruit?'),('b','All she had, Zappy. That’s why the gold came. Lakṣmī counts the heart, not the size.')],'Everything given, <b>gold returned</b>.'),
 verse('v-kanaka','Kanakadhārā Stotram, verse 1','Lakṣmī’s glance on Viṣṇu',['aṅgaṃ hareḥ pulakabhūṣaṇam āśrayantī','bhṛṅgāṅganeva mukulābharaṇaṃ tamālam','aṅgīkṛtākhilavibhūtir apāṅgalīlā','māṅgalyadāstu mama maṅgaladevatāyāḥ'],svg(200,150,'A dark tamāla tree with buds and a bee, and Lakṣmī’s glance falling on Viṣṇu',f'<rect width="200" height="150" fill="#f6e3e1"/>'+g(70,140,1,tree('#2a3a2a'))+g(140,140,1,vishnu())+'<circle cx="95" cy="60" r="4" fill="#e0a800"/>'),'May the playful side-glance of the goddess of auspiciousness bring me good fortune: the glance that rests on Hari’s body, thrilled into bloom, as a female bee rests on a dark tamāla tree adorned with buds, the glance that holds all the world’s riches.',[('aṅgaṃ hareḥ','the body of Hari'),('pulaka-bhūṣaṇam','adorned with thrills'),('bhṛṅga-aṅganā','a female bee'),('tamālam','the dark tamāla tree'),('apāṅga-līlā','the play of the side-glance'),('māṅgalya-dā','giver of auspiciousness')],'<b>A glance, not a gift.</b> Śaṅkara asks Lakṣmī not for gold but for a glance: her eye rests on Viṣṇu like a bee on a flowering tree, and wherever it falls, plenty follows. The image fits the vrata: the women ask for her look upon the house.',k='Ask for <b>her glance</b>.',note='Text as on our '+L('/devi/kanakadhara-stotram/','Kanakadhārā Stotram')+' page, which gives the full hymn.'),
 cards('bagina','BĀGINA AND ARISINA-KUṄKUMA','Sharing the goddess',fig_row('A bāgina tray, turmeric and kuṅkuma, bangles and betel leaves',[(bagina(),1.6),('<circle cx="-10" r="9" fill="#e0a800"/><circle cx="10" r="9" fill="#c0392b"/>',1.6),('<circle r="14" fill="none" stroke="#2a9d6f" stroke-width="4"/><circle r="10" fill="none" stroke="#c0392b" stroke-width="4"/>',1.4),(leaf('#3a8a3a'),1.6)],['bāgina','arisina-kuṅkuma','baḷe','vīḷyada ele'],gy=150),[('🧺','Bāgina','Small winnowing-tray or plate gifts given to married women: rice, dal, jaggery, coconut, turmeric, kuṅkuma, bangles, a comb, a mirror, a blouse piece, betel and fruit. In some families the bāgina is given in a pair, to the goddess and to the guest.'),('🟡','Arisina-kuṅkuma','Women are invited home through the day and evening for turmeric and kuṅkuma, a ritual welcome of sumaṅgalīs: each guest is treated as the goddess herself.'),('🎁','Why give','The elders say Lakṣmī stays where she is shared. A vow kept alone feels half-done.'),('👧','Girls','Little girls are dressed up and given small gifts too, as Lakṣmī’s youngest forms.')],[('z','Why give gifts to other women?'),('b','Because Lakṣmī stays where she is shared, Zappy. That’s the point of the whole day.')],'Lakṣmī, <b>shared not hoarded</b>.'),
 cards('food','THE VARAMAHĀLAKṢMĪ KITCHEN','Sweets for the goddess',fig_row('Hōḷige, pāyasa, kōsambari and a heap of fruit',[(laddu('#e0a800'),1.8),(pot_rice(),1.3),(plate(),1.6),(banana(),1.6)],['hōḷige','pāyasa','kōsambari','haṇṇu'],gy=150),[('🫓','Karnataka','<b>Hōḷige</b>, pāyasa, kōsambari, chitrānna, vaḍe and a festive meal on a plantain leaf; some homes make nine kinds of sweets.'),('🥟','Tamil Nadu and Andhra','Four kinds of kozhukkaṭṭai, vaḍai and pāyasam in Tamil homes; pūrṇam booreḷu and pulihora in Telugu homes.'),('🍎','Fruit','Nine or more kinds of fruit piled before the kalaśa: abundance on a plate.'),('🤝','Shared','Food goes to every woman who visits and to the neighbours; the fast, where kept, is broken only after the worship and the story.')],[('z','Nine kinds of fruit?'),('b','Abundance on a plate, Zappy. She’s the goddess of plenty.')],'Plenty, <b>on a plantain leaf</b>.'),
 reading('meaning','WHAT VARAMAHĀLAKṢMĪ MEANS','Prosperity, rightly understood',svg(560,150,'Eight small lamps for the eight forms of Lakṣmī around a kalaśa',f'<rect width="560" height="150" fill="#f6e3e1"/>'+g(280,140,1.3,kalasha_face())+''.join(g(280+200*__import__("math").cos(3.14+k*0.45),130+80*__import__("math").sin(3.14+k*0.45),.9,lamp()) for k in range(8))),['<b>Vara.</b> The goddess is worshipped as the giver of boons: health, long life, children, good marriage, food and wealth. The vrata asks for them openly and without shame.','<b>Eight forms.</b> Lakṣmī is not only money: tradition counts eight Lakṣmīs, of grain, courage, children, victory, knowledge, wealth and more. Read our '+L('/devi/ashta-lakshmi/','Aṣṭa Lakṣmī')+' series.','<b>Character.</b> In the story the goddess comes to Cārumatī because of her character, not her wealth; in the Kanakadhārā she comes to a poor woman because of her giving. Many teachers read the vrata as a prayer for both: plenty, and the goodness that deserves it. (Interpretation.)','<b>Sharing.</b> The bāgina and arisina-kuṅkuma turn the vow outward: the goddess is honoured in every woman who comes to the door.'],[('z','If I could do one thing for Varamahālakṣmī?'),('b','Give something you value to someone who needs it, Zappy, like the woman with the gooseberry. Then sing one verse.')],'Plenty, and <b>the goodness to share it</b>.'),
 end(i,['<b>When.</b> The Friday before Śrāvaṇa Pūrṇimā.','<b>Image.</b> A kalaśa dressed as Lakṣmī, with a face, sari and gold.','<b>Story.</b> Cārumatī’s dream; Lakṣmī from the ocean; the golden rain.','<b>Rite.</b> Pūjā, the yellow thread, the kathā; Mahālakṣmyaṣṭakam and Kanakadhārā.','<b>Sharing.</b> Bāgina, arisina-kuṅkuma, hōḷige and fruit.'],'Previous: '+L('/festivals/naga-panchami/','Nāga Pañcamī')+'. Next: '+L('/festivals/krishna-janmashtami/','Kṛṣṇa Janmāṣṭamī')+'.','Varamahālakṣmī: the boon-giving goddess'),
 sources([('Texts:','Bhāgavata Purāṇa 8.8 (Lakṣmī from the churning). Mahālakṣmyaṣṭakam and Kanakadhārā verses from our own pages. Kanakadhārā origin story from Śaṅkara’s traditional hagiographies.'),('Customs:','Wikipedia, “Varalakshmi Vratam” (date, kalaśa, thread, Tamil customs, Cārumatī and Padmāvatī stories); Karnataka practice as summarised in our earlier guide.')],'the source of the Cārumatī story (vrata booklets cite the Skanda Purāṇa; we have not traced it); place-names in the story (vary); the nine-knot thread (varies by family); bāgina contents (vary).','Interpretations are marked as such.')]
build(i,'ŚRĀVAṆA FRIDAY · THE KALAŚA · THE YELLOW THREAD',COV,'The goddess as guest','The <b>Friday</b> and its vow, the <b>stories</b> of Cārumatī, the ocean and the golden rain, two <b>hymns</b>, and every step of a Karnataka Varamahālakṣmī: kalaśa, thread, <b>bāgina</b> and food.','Varamahālakṣmī Vrata explained: the Friday before Śrāvaṇa Pūrṇimā, Cārumatī’s dream, Lakṣmī from the churning of the ocean, the Mahālakṣmyaṣṭakam and Kanakadhārā Stotram with Śaṅkara’s golden rain, the dressed kalaśa, the yellow thread, bāgina, arisina-kuṅkuma and the festive food of Karnataka.',pp)
print('vml ok',len(pp)+2)
